def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的臺灣與全球連結、流動資料及因果界線能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」涉及的流向、節點、群體、時間與空間尺度。", f"整理證據：分開記錄流動事實、受益者、成本與仍待查證的機制；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」能完整回應臺灣與世界的關聯問題。", "排除誘答：檢查是否只看總量、單一年度、單一群體或單一成功案例，並指出遺漏的資料。", "結論回查：確認因果與分配結論沒有超過證據範圍；換產業、地區或時間後要重新判讀。"]
    return {"id": f"question-social-content-geo-aa-iv-4-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-aa-iv-4"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫臺灣與世界關聯探究情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-aa-iv-4", "examPatternRefs": refs, "solutionStrategy": "先畫出跨境流動與節點，再切換地方、臺灣與全球尺度，最後以時間、統計與制度資料檢查因果和分配。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-aa-iv-4-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
